<?php
$uid = (int)$u['id'];
handle('dev_trust', function () use ($uid) { q('UPDATE devices SET trusted=? WHERE id=? AND user_id=?', [(int)$_POST['v'], (int)$_POST['id'], $uid]); return 'Device updated.'; });
handle('dev_revoke', function () use ($uid) { if ((int)$_POST['id'] === (int)$_SESSION['device_id']) throw new AppError('Use Sign out for this device.'); q('UPDATE devices SET revoked=1, trusted=0 WHERE id=? AND user_id=?', [(int)$_POST['id'], $uid]); audit($uid, 'device_revoked', 'device', (int)$_POST['id']); return 'Device signed out. Its session no longer works.'; });
handle('pw_change', function () use ($uid) { Auth::verifyPassword($uid, (string)$_POST['old']); $n = (string)$_POST['new']; if (strlen($n) < 8 || !preg_match('/[A-Za-z]/', $n) || !preg_match('/\d/', $n)) throw new AppError('New password needs 8+ characters with a letter and a number.'); q('UPDATE users SET password_hash=? WHERE id=?', [password_hash($n, PASSWORD_DEFAULT), $uid]); q('UPDATE devices SET revoked=1 WHERE user_id=? AND id<>?', [$uid, (int)$_SESSION['device_id']]); audit($uid, 'password_changed', 'user', $uid); notify($uid, 'security', 'Password changed', 'All other devices were signed out.'); return 'Password changed. Other devices were signed out.'; });
handle('pin_change', function () use ($uid) { Auth::verifyPassword($uid, (string)$_POST['password']); if (!valid_pin((string)$_POST['new'])) throw new AppError('PIN must be 4 to 6 digits.'); q('UPDATE users SET pin_hash=? WHERE id=?', [password_hash((string)$_POST['new'], PASSWORD_DEFAULT), $uid]); audit($uid, 'pin_changed', 'user', $uid); notify($uid, 'security', 'Transaction PIN changed'); return 'PIN changed.'; });
handle('risk_ack', function () use ($uid) { q("UPDATE risk_alerts SET status='reviewed' WHERE user_id=?", [$uid]); return 'Alerts marked as reviewed.'; });
handle('freeze', function () use ($uid) { $to = (int)$_POST['freeze']; q("UPDATE wallets SET frozen=?, frozen_by=? WHERE user_id=? AND (frozen_by<>'admin' OR ?=1)", [$to, $to ? 'user' : 'none', $uid, $to]); audit($uid, $to ? 'wallet_frozen' : 'wallet_unfrozen', 'user', $uid); return $to ? 'All your wallets are frozen.' : 'Wallets unfrozen (admin freezes stay in place).'; });
echo page_head('Security', 'Control devices, credentials, wallet freeze and review risk alerts.');
$devs = rows('SELECT * FROM devices WHERE user_id=? AND revoked=0 ORDER BY last_seen DESC', [$uid]); $dr = [];
foreach ($devs as $d) { $cur = (int)$d['id'] === (int)$_SESSION['device_id']; $dr[] = [e(mb_substr($d['label'], 0, 70)) . ($cur ? ' <span class="badge b-info">This device</span>' : ''), e($d['ip_address']), e(fdate($d['last_seen'])), $d['trusted'] ? badge('active') : '<span class="hint">Not trusted</span>', form_start('dev_trust', 'class="inline"') . '<input type="hidden" name="id" value="' . (int)$d['id'] . '"><input type="hidden" name="v" value="' . ($d['trusted'] ? 0 : 1) . '">' . btn($d['trusted'] ? 'Untrust' : 'Trust', 'secondary sm') . '</form>' . (!$cur ? ' ' . form_start('dev_revoke', 'class="inline"') . '<input type="hidden" name="id" value="' . (int)$d['id'] . '">' . btn('Sign out', 'danger sm') . '</form>' : '')]; }
$ra = rows('SELECT * FROM risk_alerts WHERE user_id=? ORDER BY id DESC LIMIT 10', [$uid]); $rr = []; foreach ($ra as $a) $rr[] = [e(fdate($a['created_at'])), badge($a['severity']), e($a['message']), badge($a['status'] === 'open' ? 'open' : 'completed')];
$au = rows("SELECT * FROM audit_logs WHERE user_id=? AND action IN ('login','login_failed','pin_failed','password_changed','pin_changed','device_revoked','wallet_frozen','wallet_unfrozen') ORDER BY id DESC LIMIT 8", [$uid]); $ar = []; foreach ($au as $a) $ar[] = [e(fdate($a['created_at'])), e(str_replace('_', ' ', $a['action'])), e($a['ip_address'])];
$fz = (int)val("SELECT COUNT(*) FROM wallets WHERE user_id=? AND frozen=1", [$uid]) > 0;
echo '<div class="grid g2"><div class="grid">' . card('Wallet freeze', '<p>' . ($fz ? 'Your wallets are frozen: nothing can be sent or received.' : 'Freeze all your wallets instantly if you lose a device or suspect misuse.') . '</p>' . form_start('freeze', 'class="inline"') . '<input type="hidden" name="freeze" value="' . ($fz ? 0 : 1) . '">' . btn($fz ? 'Unfreeze wallet' : 'Freeze wallet', $fz ? '' : 'danger') . '</form>') .
  card('Change password', form_start('pw_change') . field('Current password', 'old', 'password', '', 'required autocomplete="current-password"') . field('New password', 'new', 'password', '', 'required minlength="8" autocomplete="new-password"') . btn('Change password', 'secondary') . '</form>') . card('Change PIN', form_start('pin_change') . field('Account password', 'password', 'password', '', 'required autocomplete="current-password"') . field('New PIN', 'new', 'password', '', 'required inputmode="numeric" pattern="\d{4,6}" maxlength="6"') . btn(t('Change PIN'), 'secondary') . '</form>') . '</div><div class="grid">' .
  card('Trusted devices and sessions', tbl(['Device', 'IP', 'Last seen', 'Trust', ''], $dr), '') . card('Risk alerts', tbl(['When', 'Level', 'Message', 'Status'], $rr, 'No alerts. Alerts appear for new recipients, high values, bursts and blocked charges.'), form_start('risk_ack', 'class="inline"') . btn('Mark reviewed', 'secondary sm') . '</form>') . card('Recent security events', tbl(['When', 'Event', 'IP'], $ar, 'Nothing yet.')) . '</div></div>';
